// Seed the catalogue only when the products table is empty.
// Uses the shared statement API (db.prepare(...).run/get) like src/seed.js.
// price_reseller / price_usd_reseller are NOT NULL in the base schema, so
// they are filled from the silver prices — falling back to the regular
// price where a source carries no silver price (e.g. BGMI UC).
async function seedCatalogIfEmpty(db) {
  const countRow = await db.prepare('SELECT COUNT(*) AS c FROM products').get();
  if (countRow && Number(countRow.c) > 0) return { seeded: false };

  const catDefs = [
    { name: 'Mobile Legends', slug: 'mobile-legends', sort_order: 0 },
    { name: 'BGMI', slug: 'bgmi', sort_order: 1 },
  ];
  const CAT_IMAGES = {
    'mobile-legends': '/images/products/mlbb-diamonds.webp',
    'bgmi': '/images/products/bgmi-uc.webp',
  };
  const catIds = {};
  for (const cat of catDefs) {
    const existing = await db.prepare('SELECT id FROM categories WHERE slug = ?').get(cat.slug);
    if (existing) {
      catIds[cat.slug] = existing.id;
      continue;
    }
    const res = await db
      .prepare('INSERT INTO categories (name, slug, sort_order, active, image_url) VALUES (?, ?, ?, 1, ?)')
      .run(cat.name, cat.slug, cat.sort_order, CAT_IMAGES[cat.slug] || null);
    catIds[cat.slug] = res.lastInsertRowid;
  }

  const insertProduct = db.prepare(
    `INSERT INTO products
       (category_id, name, slug, description, image_url,
        price_regular, price_reseller, price_silver,
        price_usd, price_usd_reseller, price_usd_silver,
        cost_price, available_inr, available_usd, featured, active,
        busan_product_id, busan_auto_fulfil)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  );
  const insertVariant = db.prepare(
    `INSERT INTO product_variants
       (product_id, name,
        price_regular, price_reseller, price_silver,
        price_usd, price_usd_reseller, price_usd_silver,
        cost_price, busan_product_id, sort_order, active)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  );
  const insertAttr = db.prepare(
    `INSERT INTO product_checkout_attributes
       (product_id, label, field_type, required, sort_order)
     VALUES (?, ?, ?, ?, ?)`
  );

  let productCount = 0;
  let variantCount = 0;
  for (const p of CATALOG) {
    const categorySlug = p.category === 'BGMI' ? 'bgmi' : 'mobile-legends';
    const res = await insertProduct.run(
      catIds[categorySlug],
      p.name,
      p.slug,
      p.description,
      p.image_url,
      p.price_regular,
      p.price_silver != null ? p.price_silver : p.price_regular,
      p.price_silver,
      p.price_usd,
      p.price_usd_silver != null ? p.price_usd_silver : p.price_usd,
      p.price_usd_silver,
      p.cost_price,
      p.available_inr,
      p.available_usd,
      p.featured,
      1,
      p.busan_product_id,
      p.busan_auto_fulfil
    );
    const productId = res.lastInsertRowid;
    productCount += 1;
    for (const v of p.variants) {
      // USD silver is not stored in the source data — derive it from the
      // INR silver/regular ratio so USD reseller pricing works too.
      const vUsdSilver = v.price_usd_silver != null ? v.price_usd_silver
        : (v.price_usd != null && v.price_silver != null && v.price_regular > 0
          ? Math.round(v.price_usd * v.price_silver / v.price_regular * 100) / 100
          : null);
      await insertVariant.run(
        productId,
        v.name,
        v.price_regular,
        v.price_silver != null ? v.price_silver : v.price_regular,
        v.price_silver,
        v.price_usd,
        v.price_usd_silver != null ? v.price_usd_silver : v.price_usd,
        vUsdSilver,
        v.cost_price,
        v.busan_product_id,
        v.sort_order,
        v.active
      );
      variantCount += 1;
    }
    for (const a of p.attributes || []) {
      await insertAttr.run(productId, a.label, a.field_type, a.required, a.sort_order);
    }
  }

  console.log(`[avardo-catalog] seeded ${productCount} products, ${variantCount} variants`);
  return { seeded: true, products: productCount, variants: variantCount };
}

module.exports = { CATALOG, seedCatalogIfEmpty };
